#!/usr/bin/env node
// ja-proofread v0.1.15 の同梱の一式。このファイル1つで、校正したいリポジトリの .claude/ に ja-proofread を同梱する。
// plugins/ja-proofread/scripts/build-setup.mjs が作ったファイルです。手で直さないでください。
// 手元にプラグインを入れていなくても動きます（claude.ai/code のクラウドセッションの中でも）。依存はなく、Node だけで動きます。
// 中のファイルの sha256 をすべて確かめてから一時ディレクトリに書き出し、その中の install-into-project.mjs（--project-kit のときは install-project-kit.mjs）を動かして、一時ディレクトリを消します。
//
//   node ja-proofread-setup.mjs [リポジトリ]            同梱する（省略時はカレントディレクトリ。git の作業コピーの根であること）
//   node ja-proofread-setup.mjs [リポジトリ] --remove   同梱をやめる
//   node ja-proofread-setup.mjs --project-kit <ディレクトリ> [--remove]
//                                                     claude.ai/code の Projects で、リポジトリなしに使う kit を書く（消す）。
//                                                     git の作業コピーでなくてよい（docs/install-projects.md）。
//                                                     --as <使う場所> は、手元で作ってアップロードするときに、中のパスを使う場所で書く
//   node ja-proofread-setup.mjs --list                  中のファイルと sha256 を表示する
//   node ja-proofread-setup.mjs --version               版を表示する
import { existsSync, statSync, realpathSync, mkdtempSync, mkdirSync, writeFileSync, rmSync, readFileSync } from "node:fs";
import { join, resolve, dirname, isAbsolute } from "node:path";
import { tmpdir } from "node:os";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";

const VERSION = "0.1.15";
// [プラグインの中のパス, sha256, base64]
const FILES = [
[".claude-plugin/plugin.json","518e7a15716b1adee425e6eec0ae5fe001d5ea1fe2b0131f36628a54e36904dd",""],
["agents/fresh-eyes-reader.md","7a10b3426d84ba5819e2a2a3ee088bd033f12c6f2d47f214cff801c09e656719",""],
["agents/structure-reviewer.md","59ef9083e18627d1e8c6c81131ab053092d0e68108048bd325779ea9a0aff7be",""],
["config/doc.textlintrc.json","0b1ab841535f6f3316ccfccb3118cf366a07b73fbc2e672e6cb08964f9fccff8",""],
["config/slide.textlintrc.json","50981f29066053257dafeb23f2f61209097fe5912daf3ec77267771836bc27c6",""],
["data/ledger.json","b6e991266b9b43a408b2eb259e579b43c9614b2a58248a2d5209517f9b1c1ea9",""],
["data/prh.yml","9e7afcec4af8f6c922f57a8b373868e4da689f07abe1829bd099431a3fc2e292",""],
["data/settings.json","88b36f6ceb04b630a7b090da05a7b1fb7f909af32502b0fa6cb71bcb90156317",""],
["package-lock.json","8feee1e720f64ad4b62ffc57107354b796e0c898b72b60913713f6de99ea1a18",""],
["package.json","6283e25f9c7182c56dd6ba84959d2dab33afbbeddf4d2f7ea63f03a3792a1ea4",""],
["rules/ledger-patterns.js","97f0d1247a704d32e4159e31fe4b4c5357b22eb31efd6425fa92d3f8358b141b",""],
["scripts/ensure-deps.mjs","4128f1f2dade3aab68e82315183c470e56f6bea01ba1cc6175e12fef9a632541",""],
["scripts/hook-post-edit.mjs","e3df5601ad2c86098c6dda7457e59bdffacd2ceb2a9a1b59780aa8b876e60bfe",""],
["scripts/install-into-project.mjs","153e68f7533e9785293594a6b7a37e22650f92c65881eef3d3ea07c10262bc9e",""],
["scripts/install-project-kit.mjs","65d57271a1b33251a4b25706c854dfd27ae1c3b3b26e6c497c7c1eefa8a3a097",""],
["scripts/ledger.mjs","35890821f065776f09513d2632eb5ad7017c3040937c758e74bca98e7ab1cd4e",""],
["scripts/lib.mjs","d99c519f20c149e19306186e2a8dd06c88768b41fae275d4010de8ae61e3a32d",""],
["scripts/prh-load.mjs","f5957b7599c20818719633b5b429bac0cb67b3b13404e347631d5c1dbb58ed82",""],
["scripts/proofread.mjs","e6327bec165550152a6730101baa5a0e8583864644d47adf0aec1e54a89161bf",""],
["scripts/regex-safety.mjs","3817917a68c666ef78b75deca5e6ec7f16a73d5aeab781344e99fe6bb248ad5e",""],
["scripts/structure-check.mjs","891b0fe0966a39ba852327cac0f600fc38fb26392e55b0560b4147618f72d563",""],
["scripts/stylometry.mjs","bf6339336ac9d92f7f32e7a644859e89a32a7ff1b5ca3407603f3f140d07675e",""],
["skills/grow-ledger/SKILL.md","6a1f7c61a6d83031af30670cbe7fafed372e0dbfa2e33f327e1efc95840e12cd",""],
["skills/proofread/SKILL.md","105c485d3354972440b22802d7c40d1e48a84d3ba9d0bc516e83803550ebe64f",""],
["skills/write/SKILL.md","61bf3d9808714a562151292b4fc7f46f11127fc8d9c6d163a37150a615016c85",""],
["templates/ja-proofread.example.json","c08d9f8fb3ba13d1bc0ea80be6e932a40db4e811bda49d660025b3cee0c8d6cc",""],
["templates/reader-test.md","3771c68ce499516aeb273d0db4b9aebb43e53ca0c0583483579d4671a28e5de0",""],
["templates/review-checklist.md","94b4b9d18a0ec2bac232a5cb12417b21479bbdd7781ba67aec1e2a3396934ad9",""]
];

const USAGE = "使い方: node ja-proofread-setup.mjs [リポジトリ] [--remove] | --project-kit <ディレクトリ> [--as <使う場所>] [--remove] | --list | --version";
const fail = (msg, code = 1) => { console.error(msg); process.exit(code); };
const args = process.argv.slice(2);
if (args.includes("--help") || args.includes("-h")) { console.log(USAGE); process.exit(0); }
if (args.includes("--version")) { console.log(VERSION); process.exit(0); }
if (args.includes("--list")) { for (const [p, sha] of FILES) console.log(sha + "  " + p); process.exit(0); }
// --project-kit <ディレクトリ>：Projects 向けの kit を書く（git の作業コピーでなくてよい。docs/install-projects.md）
let kitDir = null;
const ki = args.indexOf("--project-kit");
if (ki >= 0) {
  kitDir = args[ki + 1];
  if (!kitDir || kitDir.startsWith("-")) fail("--project-kit のあとに kit を書くディレクトリを指定します（例：--project-kit /mnt/project-files/ja-proofread-kit）\n" + USAGE, 2);
  args.splice(ki, 2);
}
// --as <使う場所>：手元で kit を作ってプロジェクトの Context にアップロードするとき、手順と指示の中のパスを使う場所で書く
let asPath = null;
const ai = args.indexOf("--as");
if (ai >= 0) {
  asPath = args[ai + 1];
  if (!kitDir) fail("--as は --project-kit と一緒に使います\n" + USAGE, 2);
  if (!asPath || !asPath.startsWith("/")) fail("--as のあとに、kit を使う場所を / で始まるパスで指定します（例：--as /mnt/project-files/ja-proofread-kit）\n" + USAGE, 2);
  args.splice(ai, 2);
}
const unknown = args.filter((a) => a.startsWith("-") && a !== "--remove");
if (unknown.length) fail("知らないオプションです: " + unknown.join(" ") + "\n" + USAGE, 2);
const pos = args.filter((a) => !a.startsWith("-"));
if (kitDir && pos.length) fail("--project-kit のときは、リポジトリは指定しません\n" + USAGE, 2);
if (pos.length > 1) fail("リポジトリは1つだけ指定します\n" + USAGE, 2);
const remove = args.includes("--remove");
const target = resolve(kitDir ?? pos[0] ?? process.cwd());
if (!kitDir && (!existsSync(target) || !statSync(target).isDirectory())) fail(target + " はディレクトリではありません\n" + USAGE, 2);

// 書く前に、すべてのファイルの sha256 を確かめる（壊れていれば何も書かない）
const bufs = [];
for (const [p, sha, b64] of FILES) {
  if (typeof p !== "string" || !p || isAbsolute(p) || p.split("/").some((s) => s === ".." || s === "")) fail("中のファイルの名前がおかしいので止めました: " + p);
  const buf = Buffer.from(b64, "base64");
  const got = createHash("sha256").update(buf).digest("hex");
  if (got !== sha) fail(p + " の sha256 が合わないので、何も書かずに止めました（期待 " + sha + "、実際 " + got + "）。このファイルが壊れているので、取り直してください");
  bufs.push([p, buf]);
}
// 中のファイルを一時ディレクトリに書き出し、その中のスクリプトを動かす
const runInside = (script, scriptArgs, stdio) => {
  const work = mkdtempSync(join(tmpdir(), "ja-proofread-setup-"));
  try {
    for (const [p, buf] of bufs) {
      const dest = join(work, p);
      mkdirSync(dirname(dest), { recursive: true });
      writeFileSync(dest, buf);
    }
    const r = spawnSync(process.execPath, [join(work, "scripts", script), ...scriptArgs], { stdio, encoding: "utf8" });
    if (r.error) console.error(r.error.message);
    return r;
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
};

if (kitDir) {
  const r = runInside("install-project-kit.mjs", [target, ...(asPath ? ["--as", asPath] : []), ...(remove ? ["--remove"] : [])], "inherit");
  process.exit(r.status ?? 1);
}

// git の作業コピーの根でなければ止める（.claude/ はリポジトリの根に置かないと読まれないため）
const git = (a, opts = {}) => spawnSync("git", a, { cwd: target, encoding: "utf8", ...opts });
const top = git(["rev-parse", "--show-toplevel"]);
if (top.error) fail("git が見つかりません。git の作業コピーの根で動かしてください（" + top.error.message + "）");
if (top.status !== 0) fail(target + " は git の作業コピーではありません。校正したいリポジトリの根を指定してください（リポジトリなしで Projects に入れるときは --project-kit を使います）\n" + (top.stderr || "").trim());
const root = top.stdout.trim();
if (realpathSync(root) !== realpathSync(target)) fail(target + " は git の作業コピーの根ではありません。根（" + root + "）を指定してください");

// やめるときにステージするパスは、やめる前の一覧（vendored.json）から作る
const readManifest = () => { try { return JSON.parse(readFileSync(join(target, ".claude", "ja-proofread", "vendored.json"), "utf8")); } catch { return null; } };
const names = (v, re) => (Array.isArray(v) ? v.filter((x) => typeof x === "string" && re.test(x)) : []);
const before = readManifest();
// 同梱があるか（install-into-project.mjs と同じ見方：.claude/ja-proofread/ があるか、settings.json に同梱のフックがあるか）。
// やめるときに同梱が無ければ、install-into-project.mjs が「同梱されていません」と出して何も変えないので、コミットの例も出さない
const hasOurHooks = () => {
  try {
    const st = JSON.parse(readFileSync(join(target, ".claude", "settings.json"), "utf8"));
    return Object.values(st?.hooks || {}).some((gs) => Array.isArray(gs) && gs.some((g) => (g?.hooks || []).some((h) => String(h?.command || "").includes(".claude/ja-proofread/scripts/"))));
  } catch { return false; }
};
const vendoredBefore = before !== null || existsSync(join(target, ".claude", "ja-proofread")) || hasOurHooks();

// install-into-project.mjs の「コミットするパス」の行（ja-proofread-* の書き方）は、下で同梱したものの名前だけの行に置き換える
const ir = runInside("install-into-project.mjs", [target, ...(remove ? ["--remove"] : [])], ["inherit", "pipe", "inherit"]);
process.stdout.write((ir.stdout || "").split("\n").filter((l) => !l.startsWith("コミットするパス：")).join("\n"));
const status = ir.status ?? 1;
if (status !== 0) process.exit(status);
if (remove && !vendoredBefore) process.exit(0);

const q = (s) => (/^[A-Za-z0-9_\/.:@%+=,-]+$/.test(s) ? s : "'" + s.replace(/'/g, "'\\''") + "'");
const manifest = remove ? before : readManifest();
const skills = names(manifest?.skills, /^ja-proofread-[A-Za-z0-9_-]+$/);
const agents = names(manifest?.agents, /^ja-proofread-[A-Za-z0-9_.-]+\.md$/);
let paths = [".claude/ja-proofread", ...skills.map((n) => ".claude/skills/" + n), ...agents.map((f) => ".claude/agents/" + f), ".claude/settings.json"];
if (remove) {
  // 消えたもののうち、コミットしていたものだけをステージする（無いパスを git add に渡すと失敗するため）
  paths = paths.filter((p) => existsSync(join(target, p)) || git(["ls-files", "--", p]).stdout.trim());
  console.log("\nコミットするパス：" + (paths.join(" ") || "（なし）"));
  if (paths.length) console.log("コミットしてプッシュする例：\n  cd " + q(target) + " && git add -A -- " + paths.join(" ") + ' && git commit -m "ja-proofread の同梱をやめる" && git push -u origin HEAD');
} else {
  paths.push(".ja-proofread.json");
  const ignored = paths.filter((p) => git(["check-ignore", "-q", "--", p]).status === 0);
  console.log("\nコミットするパス：" + paths.join(" "));
  if (ignored.length) console.log("注意：" + ignored.join(" ") + " は .gitignore で除かれています。.gitignore を直すか、git add -f で足してください");
  console.log("コミットしてプッシュする例：\n  cd " + q(target) + " && git add " + paths.join(" ") + ' && git commit -m "ja-proofread を同梱" && git push -u origin HEAD');
  console.log("プッシュしたら、新しいセッションを始めてください。起動のときの依存の準備（SessionStart のフック）と書いた直後の校正は、新しいセッションから動きます。");
}
